const PROGRAMS_CSS=":root{--bg:#F7F7FA;--paper:#fff;--ink:#102332;--muted:#4D5F70;--soft:#55667A;--line:#DCE4EA;--plum:#795094;--plum-dark:#5E3C74;--plum-lite:#F3ECF7;--rail:#2B3546;--rail2:#36425A;--green:#1E7A4F;--amber:#8A5A0E;--red:#B42335;--dark:#182C35}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif}
button,input,select,textarea{font:inherit;color:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}
:focus-visible{outline:3px solid #A57FC0;outline-offset:2px}
.pg-shell{display:grid;grid-template-columns:224px minmax(0,1fr);min-height:760px;background:var(--bg)}
.pg-rail{background:var(--rail);color:#EEF1F6;padding:22px 12px;display:flex;flex-direction:column;gap:18px;min-width:0}
.pg-brand{display:flex;flex-direction:column;padding:0 10px 14px;border-bottom:1px solid #3E4A60}.pg-brand strong{font-size:17px;letter-spacing:-.2px}.pg-brand span{font-size:12px;color:#BDC5D3}
.pg-nav{display:flex;flex-direction:column;gap:3px}.pg-nav button{display:flex;align-items:center;gap:10px;width:100%;border:0;border-radius:9px;background:transparent;color:#CDD3DE;padding:10px 11px;text-align:left;font-size:14px;font-weight:560;min-height:42px}.pg-nav button:hover{background:var(--rail2);color:#fff}.pg-nav button[aria-current="page"]{background:#4A3A5E;color:#fff;font-weight:700}.pg-ico{display:flex;width:18px;height:18px;flex:none}
.pg-rail-foot{margin-top:auto;font-size:12px;color:#BDC5D3;padding:12px 10px;border-top:1px solid #3E4A60;line-height:1.6}
.pg-main{min-width:0;padding:26px clamp(16px,3vw,36px) 48px;max-width:1440px;width:100%;margin:0 auto}
